struct EmbeddedPng { const std::uint8_t* data; std::size_t len; };
inline EmbeddedPng find(const char* path) {
  if (!path) return {nullptr, 0};
  // Accept short names and assets-relative paths.
  // favorite
  if (std::strcmp(path, "icons/favorite.png") == 0 ||
      std::strcmp(path, "favorite.png") == 0)
    return {k_favorite_png, k_favorite_png_len};
  if (std::strcmp(path, "icons/check.png") == 0 ||
      std::strcmp(path, "check.png") == 0)
    return {k_check_png, k_check_png_len};
  if (std::strcmp(path, "icons/add.png") == 0 ||
      std::strcmp(path, "add.png") == 0)
    return {k_add_png, k_add_png_len};
  return {nullptr, 0};
}
